CREATE TABLE IF NOT EXISTS teams (id BIGSERIAL PRIMARY KEY, api_id BIGINT UNIQUE NOT NULL, code TEXT, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS players (id BIGSERIAL PRIMARY KEY, api_id BIGINT UNIQUE, name TEXT NOT NULL, name_normalized TEXT NOT NULL, team_id BIGINT REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS games (id BIGSERIAL PRIMARY KEY, api_id BIGINT UNIQUE NOT NULL, date_utc TIMESTAMPTZ NOT NULL, season INTEGER NOT NULL, home_team_id BIGINT REFERENCES teams(id), away_team_id BIGINT REFERENCES teams(id), home_pts INTEGER, away_pts INTEGER, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS player_games (player_id BIGINT NOT NULL REFERENCES players(id), game_id BIGINT NOT NULL REFERENCES games(id), team_id BIGINT NOT NULL REFERENCES teams(id), opp_team_id BIGINT NOT NULL REFERENCES teams(id), home BOOLEAN NOT NULL, min NUMERIC, pts INTEGER, reb INTEGER, ast INTEGER, fg3m INTEGER, fgm INTEGER, fga INTEGER, ftm INTEGER, fta INTEGER, stl INTEGER, blk INTEGER, tov INTEGER, plus_minus INTEGER, source TEXT NOT NULL CHECK(source IN ('api','screenshot')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(player_id,game_id));
CREATE TABLE IF NOT EXISTS projections (id BIGSERIAL PRIMARY KEY, player_id BIGINT NOT NULL REFERENCES players(id), game_id BIGINT NOT NULL REFERENCES games(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), proj_pts DOUBLE PRECISION, proj_reb DOUBLE PRECISION, proj_ast DOUBLE PRECISION, proj_fg3m DOUBLE PRECISION, proj_pra DOUBLE PRECISION, sd_pts DOUBLE PRECISION, sd_reb DOUBLE PRECISION, sd_ast DOUBLE PRECISION, sd_fg3m DOUBLE PRECISION, sd_pra DOUBLE PRECISION);
CREATE INDEX IF NOT EXISTS projections_player_game_time ON projections(player_id,game_id,created_at);
CREATE TABLE IF NOT EXISTS update_log (id BIGSERIAL PRIMARY KEY, run_at TIMESTAMPTZ NOT NULL DEFAULT now(), type TEXT NOT NULL CHECK(type IN ('auto','screenshot','backfill')), calls_used INTEGER NOT NULL DEFAULT 0, games_added INTEGER NOT NULL DEFAULT 0, rows_added INTEGER NOT NULL DEFAULT 0, errors JSONB NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS api_call_budget (utc_date DATE PRIMARY KEY, calls_used INTEGER NOT NULL DEFAULT 0 CHECK(calls_used BETWEEN 0 AND 90), last_call_at TIMESTAMPTZ);
